import{_ as n,o as a,c as t,ai as s}from"./chunks/framework.BxxKhjs3.js";const o="/pub-blog/assets/zh.BQhvBj8_.png",i="/pub-blog/assets/ReActAgent.Dc9tS1RT.png",r="/pub-blog/assets/WorkflowAgent.JudX0BFE.png",g="/pub-blog/assets/image-20260423095322174.Cs8lYr4r.png",l="/pub-blog/assets/image-20260423100018398.B5snzhvY.png",p="/pub-blog/assets/image-20260423140104941.DAZ4qOOe.png",m="/pub-blog/assets/image-20260423135651974.DeLr-H9E.png",c="/pub-blog/assets/image-20260423135828213.We934epo.png",u="/pub-blog/assets/image-20260423135845085.mChs--Lr.png",h="/pub-blog/assets/image-20260423140234222.Dw4Yl4xW.png",w="/pub-blog/assets/image-20260423140311633.BFATlYHz.png",d="/pub-blog/assets/image-20260423140336187.BUFH4mGQ.png",A="/pub-blog/assets/image-20260423140406263.BaSVOqPm.png",b="/pub-blog/assets/image-20260423140423948.D9qlWIyt.png",_="/pub-blog/assets/image-20260423140507426.D9h26Jil.png",k="/pub-blog/assets/image-20260423141333085.Dhp2iiUL.png",T="/pub-blog/assets/image-20260423142209473.CCTJF5aX.png",C="/pub-blog/assets/image-20260423142421574.CcDlpx9c.png",J="/pub-blog/assets/image-20260423142454316.CgTcD6Eh.png",f="/pub-blog/assets/image-20260423142517587.BALW8Nhn.png",q="/pub-blog/assets/image-20260423144337786.CCyKTaMC.png",P="/pub-blog/assets/image-20260423144352415.D0sWeK1A.png",R="/pub-blog/assets/image-20260423145550856.Di9CcEx9.png",L="/pub-blog/assets/image-20260423145053102.DXvpEP5l.png",I="/pub-blog/assets/image-20260423145139940.BHUxr8ie.png",x="/pub-blog/assets/image-20260423145221387.C0Sd8dYR.png",y=JSON.parse('{"title":"利用 JiuwenClaw AgentTeam 打造自动化研发团队","description":"","frontmatter":{},"headers":[],"relativePath":"AI人工智能/基于 JiuwenClaw AgentTeam 构建自动化研发团队/基于 JiuwenClaw AgentTeam 构建自动化研发团队.md","filePath":"AI人工智能/基于 JiuwenClaw AgentTeam 构建自动化研发团队/基于 JiuwenClaw AgentTeam 构建自动化研发团队.md","lastUpdated":1777001886000,"__rawMarkdown":"# 利用 JiuwenClaw AgentTeam 打造自动化研发团队\\n\\n> 本文介绍如何通过 **JiuwenClaw AgentTeam** 构建自动化研发团队，实现字幕软件开发、AtomGit Issue/PR 智能处理与飞书文档同步。\\n\\n## 目录\\n\\n- [JiuwenClaw 平台概述](#jiuwenclaw-平台概述)\\n  - [系统架构](#系统架构)\\n  - [预置智能体类型](#预置智能体类型)\\n- [什么是 AgentTeams](#什么是-agentteams)\\n- [飞书群中添加机器人](#飞书群中添加机器人)\\n- [开启 AgentTeams](#开启-agentteams)\\n- [工作流程](#工作流程)\\n- [自动处理 PR](#自动处理-pr)\\n  - [模拟生成 PR](#模拟生成-pr)\\n- [自动生成飞书日报](#自动生成飞书日报)\\n  - [JiuwenClaw 接入飞书 lark-cli](#jiuwenclaw-接入飞书-lark-cli)\\n  - [授权给 lark-cli](#授权给-lark-cli)\\n- [总结](#总结)\\n\\n## JiuwenClaw 平台概述\\n\\n**openJiuwen** 是一个开源的 AI Agent 平台，其核心目标是为开发者提供灵活、强大且易于使用的 AI Agent 开发与运行环境。\\n\\n借助这一平台，开发者能够迅速搭建起可处理各种复杂度的 AI Agent，实现多个 Agent 之间的协作互动，从而高效地打造出生产级别的可靠 AI Agent。同时，该平台也帮助企业和个人用户快速构建自己的 AI Agent 系统或平台，促进商用级 Agentic AI 技术的广泛落地应用。\\n\\n### 系统架构\\n\\nopenJiuwen 的整体架构由三大核心模块构成：**openJiuwen Core**、**openJiuwen Studio** 以及 **openJiuwen Ops**。\\n\\n![系统架构图](assets/zh.png)\\n\\n在开发阶段，openJiuwen 提供了 Agent 编排与构建能力，让开发者能够快速创建 Agent 并进行高效开发。\\n\\n### 预置智能体类型\\n\\n目前，openJiuwen 提供了两种预置智能体类型，为用户提供丰富的功能和灵活的开发选项，以适应不同场景下的智能化需求：\\n\\n- **ReActAgent**：这是一种基于 ReAct（推理 + 行动）规划范式的 Agent。它通过「思考 → 行动 → 观察」的循环迭代过程来完成任务。ReActAgent 拥有强大的多轮推理和自我纠错能力，能够进行动态决策并灵活适应环境变化，特别适合那些需要复杂推理和策略调整的任务场景。\\n\\n  ![ReActAgent 架构](assets/ReActAgent.png)\\n\\n- **Workflow Agent**：这是一种面向多步骤任务的流程自动化 Agent，严格按照用户预设的任务流程来高效执行复杂任务。它强调通过预定义流程实现任务的规范化与高效执行，适用于任务结构清晰、能够分解为多个明确步骤的场景。\\n\\n  ![Workflow Agent 架构](assets/WorkflowAgent.png)\\n\\n## 什么是 AgentTeams\\n\\n**AgentTeams** 是 **Leader-Teammate** 协作框架，通过 **Leader**（负责人）和 **Teammates**（队友）的协同工作完成复杂任务。相比直接使用 **TeamRuntime**，**AgentTeams** 提供了更高层次的抽象，支持跨进程执行、持久化状态和自动恢复，适用于需要进程隔离、长期运行或崩溃恢复的场景，比如本文中介绍的——使用 **AgentTeams** 打造**自动化研发团队**。\\n\\nAgentTeams 支持信息实时通信和持久化，依赖两大核心层：\\n\\n- **Transport（传输层）**：负责智能体间消息传递\\n- **Storage（存储层）**：持久化团队状态、任务列表和消息\\n\\n## 飞书群中添加机器人\\n\\n> **参考文档**：[飞书频道配置指南](https://gitcode.com/openJiuwen/jiuwenclaw/blob/develop/docs/zh/%E9%A2%91%E9%81%93.md#%E9%A3%9E%E4%B9%A6)\\n\\n在飞书群聊中，添加创建好的飞书机器人后，用户可以直接在群聊中对话。飞书机器人负责接收用户的指令，并代理用户与 **JiuwenClaw** 进行交互。\\n\\n![飞书群机器人](assets/image-20260423095322174.png)\\n\\n## 开启 AgentTeams\\n\\n在飞书对话中，输入以下命令即可主动开启 AgentTeams 模式：\\n\\n```bash\\n/mode team\\n```\\n\\n然后可以直接输入需求来安排任务。\\n\\n![开启 AgentTeams 模式](assets/image-20260423100018398.png)\\n\\n## 工作流程\\n\\n整体工作流程如下图所示：\\n\\n![工作流程概览](assets/image-20260423140104941.png)\\n\\nAgentTeams 的标准协作流程包含以下步骤：\\n\\n1. **Leader** 接收到任务后，开始拆分任务\\n2. **Leader** 布置任务\\n3. **Teammate** 认领任务\\n4. **Teammate** 执行任务\\n5. **Leader** 和 **Teammate** 之间相互通信\\n6. **Teammate** 汇报任务进度\\n7. **Leader** 总结工作\\n\\n以下是各阶段的操作截图：\\n\\n**步骤 1-2：任务拆分与布置**\\n\\n![Leader 拆分任务](assets/image-20260423135651974.png)\\n\\n**步骤 3-4：任务认领与执行**\\n\\n![Teammate 执行任务](assets/image-20260423135828213.png)\\n\\n![任务执行中](assets/image-20260423135845085.png)\\n\\n![任务执行过程](assets/image-20260423140234222.png)\\n\\n![代码生成](assets/image-20260423140311633.png)\\n\\n![持续执行](assets/image-20260423140336187.png)\\n\\n**步骤 5-6：通信与汇报**\\n\\n![通信汇报](assets/image-20260423140406263.png)\\n\\n![任务汇报](assets/image-20260423140423948.png)\\n\\n**步骤 7：总结**\\n\\n![Leader 总结](assets/image-20260423140507426.png)\\n\\n### 结束\\n\\n当所有任务完成后，Leader 会输出最终的总结报告。\\n\\n![任务结束](assets/image-20260423141333085.png)\\n\\n## 自动处理 PR\\n\\n> **工具地址**：[https://atomgit.com/GitCode/ag-cli](https://atomgit.com/GitCode/ag-cli)\\n\\n> 可以在 **JiuwenClaw** 中配置 **AtomGit** 的 CLI 工具，设置监听后自动处理审核和合并 PR。\\n>\\n> ⚠️ **注意**：监听需要提供公网域名，用来接收 AtomGit 的 Webhooks 通知。\\n\\n**AtomGit** 提供了 `ag-cli` 工具，可以在 **JiuwenClaw** 中接入。接入后，**AgentTeams** 即可通过它来管理代码仓库，并自动实现 PR 的管理。\\n\\n![ag-cli 配置](assets/image-20260423142209473.png)\\n\\n可以参考文档在系统中安装 `ag-cli`，也可以直接将文档提供给 **JiuwenClaw** 进行安装。\\n\\n![安装 ag-cli](assets/image-20260423142421574.png)\\n\\n安装到最后，需要手动进行授权。\\n\\n![授权步骤 1](assets/image-20260423142454316.png)\\n\\n![授权步骤 2](assets/image-20260423142517587.png)\\n\\n### 模拟生成 PR\\n\\n> PR 的生成主要演示了 **JiuwenClaw** 有能力接管 **AtomGit**。\\n\\n![PR 生成演示 1](assets/image-20260423144337786.png)\\n\\n![PR 生成演示 2](assets/image-20260423144352415.png)\\n\\n## 自动生成飞书日报\\n\\n> **参考文档**：[飞书 CLI 官方文档](https://open.larksuite.com/document/mcp_open_tools/feishu-cli-let-ai-actually-do-your-work-in-feishu)\\n\\n![飞书日报](assets/image-20260423145550856.png)\\n\\n飞书推出了 `lark-cli` 终端工具，可以在 **JiuwenClaw** 中接入和使用。接入后，**JiuwenClaw** 便具备了操作飞书文档的能力。\\n\\n当然，**JiuwenClaw** 本身已接入飞书机器人，也可以直接给该机器人开通相关权限来操作飞书文档。\\n\\n### JiuwenClaw 接入飞书 lark-cli\\n\\n![接入 lark-cli](assets/image-20260423145053102.png)\\n\\n### 授权给 lark-cli\\n\\n![授权步骤 1](assets/image-20260423145139940.png)\\n\\n![授权步骤 2](assets/image-20260423145221387.png)\\n\\n## 总结\\n\\n通过 **JiuwenClaw AgentTeam** 的 Leader-Teammate 协作框架，我们可以轻松打造一支 **7×24 小时在线的自动化研发团队**。从需求拆解、任务分配到执行汇报，Leader 与 Teammate 之间的高效协同，让复杂项目的推进变得井然有序。\\n\\n本文以三大实战场景为例——**字幕软件开发**、**AtomGit Issue/PR 智能化处理**、**飞书文档同步与日报生成**——展示了 AgentTeams 在真实研发流程中的落地价值。借助飞书机器人作为交互入口，结合 `ag-cli` 和 `lark-cli` 等工具链，AI Agent 不仅能写代码，还能管理代码仓库、操作协作平台，真正融入团队的工作流。\\n\\n未来，随着 AgentTeams 在更多业务场景中的深入应用，人机协作的研发模式将成为提升团队效率的关键杠杆。\\n\\n\\n\\n## 相关引用\\n\\n1. [https://atomgit.com/openJiuwen](https://atomgit.com/openJiuwen?utm_source=csdn)  **欢迎star**\\n2. [https://www.openjiuwen.com](https://www.openjiuwen.com?utm_source=csdn)"}'),E={name:"AI人工智能/基于 JiuwenClaw AgentTeam 构建自动化研发团队/基于 JiuwenClaw AgentTeam 构建自动化研发团队.md"};function j(G,e,B,v,D,W){return a(),t("div",null,[...e[0]||(e[0]=[s("",79)])])}const F=n(E,[["render",j]]);export{y as __pageData,F as default};
